/* reconstructed from measured tokens */
body { font-family: "Nunito", Arial, sans-serif; color: #212529; background: #FFFFFF; }
h1, h2, h3 { font-family: "-apple-system", Arial, sans-serif; }
a { color: #607393; }
.site-header, .main-menu { background: #142954; color: #FFFFFF; }
.footer { background: #142954; color: #FFFFFF; }

header {
  height: 189px;
}
.header-wrapper {
  left: 0;
  top: 0;
  width: 100%;
  position: fixed;
  z-index: 1030;
}
header .navigation {
  font-family: 'SSP-Regular';
  font-weight: 600;
  background-color: #2e345f;
  text-transform: uppercase;
}
header .navigation .menu li > a {
  color: #ffffff;
  padding: 22px 0;
}
.btn.purple {
  background-color: #41385a;
  color: #ffffff;
  border-radius: 3px;
}
.top-news h3 {
  font-family: Calibri-Bold, sans-serif;
  color: #222222;
}

header .navigation {
  font-size: 15px;
  font-family: 'SSP-Regular';
  font-weight: 600;
  background-color: #2e345f;
  text-transform: uppercase;
}
body {
